import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def f(g):
    # find nonzero cells, cluster by connectivity of same color
    h,w=len(g),len(g[0])
    seen=set(); shapes=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                col=g[i][j]; stack=[(i,j)]; seen.add((i,j)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and g[ny][nx]==col:
                                seen.add((ny,nx)); stack.append((ny,nx))
                shapes.append(cells)
    shapes.sort(key=lambda c: min(x for _,x in c))
    out=[]
    for c in shapes:
        ys=[y for y,_ in c]; xs=[x for _,x in c]
        y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
        block=[[g[y][x] if g[y][x]==c[0] and (y,x) in c else 0 for x in range(x0,x1+1)] for y in range(y0,y1+1)]
        if not out: out=block
        else:
            for r,b in zip(out,block): r.extend(b)
    return out
print(f(G['Demo pair 1 input'])==G['Demo pair 1 output'])
print(f(G['Test input']))

